// Shared boot helper for the test/test-render-*.js suite. Compiles the WAT
// module, instantiates it with the canvas-backed host imports, and returns
// { instance, exports, renderer, canvas, memory } so individual render tests
// can build their dialog and call renderer.repaint().
//
// Each render test:
//   1. Calls bootRenderHarness({ extraHostOverrides? })
//   2. Builds whatever dialog/control it wants to draw via the test_create_*
//      exports.
//   3. Calls renderer.repaint().
//   4. Asserts the canvas has been written to (assertCanvasNonEmpty) and
//      writes the PNG to test/output/{name}.png for visual inspection.
//
// Tests fail with non-zero exit if the canvas is unchanged from the
// post-construction default (a sign WM_PAINT didn't reach the WAT wndprocs
// or the JS draw fallback was silently used).
const fs = require('fs');
const path = require('path');
const Module = require('module');
const evaluatedSource = module.renderSource || fs.readFileSync(__filename);
let replacement;

// Mount the fonts a real host mounts. Every guest glyph now comes from a strike
// the VFS supplies, so a harness with an empty font directory draws no text at
// all — which used to be masked by the Canvas text fallback. Tests that want to
// prove behaviour with a face missing should delete that one mount, not rely on
// the harness starting out bare.
function mountBundledFonts(ctx, { scalable = true } = {}) {
  const { fontMounts, BUNDLED_BITMAP_FONTS } = require('../lib/font-substitutions');
  if (!ctx || !ctx.vfs) return;
  const root = path.join(__dirname, '..');
  ctx.vfs.dirs.add('c:\\windows');
  ctx.vfs.dirs.add('c:\\windows\\fonts');
  const mount = (vfsPath, file) => {
    if (!fs.existsSync(file)) throw new Error(`missing bundled font: ${file}`);
    ctx.vfs.files.set(vfsPath, {
      data: new Uint8Array(fs.readFileSync(file)), attrs: 0x20,
    });
  };
  for (const name of BUNDLED_BITMAP_FONTS) {
    mount(`c:\\windows\\fonts\\${name.toLowerCase()}`, path.join(root, 'fonts', name));
  }
  if (!scalable) return;
  const manifest = JSON.parse(fs.readFileSync(
    path.join(root, 'fonts', 'substitutions.json'), 'utf8'));
  for (const item of fontMounts(manifest, { subset: true })) {
    mount(item.vfsPath, path.join(root, 'fonts', item.file));
  }
}

// The canonical compiler is WATX (see test/compile-src.js): lib/compile-wat.js's
// compileWat was retired for full-tree builds, so this harness now compiles
// exactly what tools/build.sh ships.
//
// extraWat keeps its old semantics: every src/*.wat fragment is self-balanced
// since b1c221d8 — the `(module` wrapper comes from the closure entry file, not
// from 13-exports.wat — so the fragment is simply APPENDED to 13-exports.wat.
// The old form spliced it in front of a trailing `)` that no longer exists,
// which matched nothing and silently dropped every extraWat export.
const harnessWasmCache = new Map();
function compileHarnessWasm(extraWat, tailCalls) {
  const { identity, compileHarness } = require('./render-artifact');
  const options = { extraWat: extraWat ? String(extraWat) : '', tailCalls: !!tailCalls };
  const key = JSON.stringify(identity(options, evaluatedSource));
  if (harnessWasmCache.has(key)) return harnessWasmCache.get(key);
  const { bytes, identity: compiledIdentity } = compileHarness(options, evaluatedSource);
  if (JSON.stringify(compiledIdentity) !== key)
    throw new Error('render artifact inputs changed before compilation');
  // Retain only the current module; changing inputs must not accumulate Wasm.
  harnessWasmCache.clear();
  harnessWasmCache.set(key, bytes);
  return bytes;
}

async function bootRenderHarness({
  extraHostOverrides = {}, extraWat = '', width = 640, height = 480,
  fonts = 'all', memory: suppliedMemory = null, tailCalls = true,
  prebuiltModule = null,
} = {}) {
  // Explicit commands can run the real test entrypoint to capture its unchanged
  // extraWat. Preparation exits before host dependencies, memory or assertions.
  const prepare = process.env.WINE_RENDER_ARTIFACT_PREPARE;
  const artifact = process.env.WINE_RENDER_ARTIFACT;
  if (prepare !== undefined && artifact !== undefined)
    throw new Error('render artifact prepare and consume modes are mutually exclusive');
  if ((prepare !== undefined || artifact !== undefined) && prebuiltModule !== null)
    throw new Error('render artifact mode cannot be combined with prebuiltModule');
  if (prebuiltModule !== null && (!(prebuiltModule instanceof WebAssembly.Module) || extraWat))
    throw new Error('prebuiltModule requires a compiled WebAssembly.Module and no extraWat');
  if (prepare !== undefined) {
    require('./render-artifact').prepareArtifact(prepare, { extraWat, tailCalls }, evaluatedSource);
    process.stderr.write('PREPARATION ONLY: render artifact written; host, native module and test assertions not run\n');
    process.exit(0);
  }
  const wasmBytes = prebuiltModule || (artifact !== undefined
    ? require('./render-artifact').consumeArtifact(artifact, { extraWat, tailCalls }, evaluatedSource)
    : compileHarnessWasm(extraWat, tailCalls));
  const { createCanvas } = require('../lib/canvas-compat');
  const { createHostImports } = require('../lib/host-imports');
  const { Win98Renderer } = require('../lib/renderer');
  const memory = suppliedMemory ||
    new WebAssembly.Memory({ initial: 8192, maximum: 8192, shared: true });
  const canvas = createCanvas(width, height);
  const renderer = new Win98Renderer(canvas);
  const ctx = {
    getMemory: () => memory.buffer,
    renderer,
    resourceJson: { menus: {}, dialogs: {}, strings: {}, bitmaps: {} },
    onExit: () => {},
  };
  const base = createHostImports(ctx);
  // 'all' mirrors a real host; 'bitmap' gives only the stock strikes, for tests
  // that need a scalable face to be genuinely missing; 'none' mounts nothing.
  if (fonts !== 'none') mountBundledFonts(ctx, { scalable: fonts === 'all' });
  base.host.memory = memory;
  base.host.create_thread = () => 0;
  base.host.exit_thread   = () => 0;
  base.host.terminate_thread = () => 0;
  base.host.create_event  = () => 0;
  base.host.set_event     = () => 0;
  base.host.reset_event   = () => 0;
  base.host.wait_single   = () => 0;
  base.host.wait_multiple = () => 0;
  base.host.com_create_instance = () => 0x80004002;
  Object.assign(base.host, extraHostOverrides);
  const result = await WebAssembly.instantiate(wasmBytes, base);
  const instance = prebuiltModule ? result : result.instance;
  const module = prebuiltModule || result.module;
  const e = instance.exports;
  ctx.exports = e;
  renderer.wasm = instance;
  renderer.wasmMemory = memory;
  return { instance, module, exports: e, renderer, canvas, memory, hostCtx: ctx, host: base.host, gdi: base.gdi };
}

// Sample the canvas at every 16x16 grid cell. Returns the count of unique
// (r,g,b) tuples we see. A blank/teal-only canvas yields 1; anything that
// drew bevels, text, swatches, etc. produces many more.
function countUniqueColors(canvas) {
  const ctx = canvas.getContext('2d');
  const { width, height } = canvas;
  const data = ctx.getImageData(0, 0, width, height).data;
  const seen = new Set();
  for (let y = 0; y < height; y += 4) {
    for (let x = 0; x < width; x += 4) {
      const i = (y * width + x) * 4;
      seen.add((data[i] << 16) | (data[i + 1] << 8) | data[i + 2]);
    }
  }
  return seen.size;
}

// Check that a specific pixel is approximately the expected COLORREF
// (0x00BBGGRR style — we accept either RGB or BGR ordering since CSS uses
// RGB but Win32 uses BGR; tests can pass whichever is convenient).
function pixelMatches(canvas, x, y, r, g, b, tol = 4) {
  const ctx = canvas.getContext('2d');
  const d = ctx.getImageData(x, y, 1, 1).data;
  return Math.abs(d[0] - r) <= tol && Math.abs(d[1] - g) <= tol && Math.abs(d[2] - b) <= tol;
}

function writePng(canvas, name) {
  const outDir = path.join(__dirname, 'output');
  if (!fs.existsSync(outDir)) fs.mkdirSync(outDir, { recursive: true });
  const out = path.join(outDir, name);
  fs.writeFileSync(out, canvas.toBuffer('image/png'));
  return out;
}

// Drive WM_NCPAINT for top-level windows and WM_PAINT for every WAT-managed
// child slot, so chrome + control visuals land on the back-canvas before we
// composite. In a real run this is driven by the dialog message pump
// (09b-dispatch.wat); the headless harness has no pump, so we simulate it.
function flushPendingPaints(harness) {
  const r = harness.renderer;
  const e = harness.exports;
  if (!r || !e || !e.send_message || !e.wnd_slot_hwnd) return;
  for (const win of Object.values(r.windows)) {
    if (win.isChild || !win.visible || !(win.w > 0 && win.h > 0)) continue;
    if (typeof r._defwndprocNcpaint === 'function') {
      r._defwndprocNcpaint(win, win.x, win.y, win.w, win.h);
    }
  }
  // Walk every slot; deliver WM_PAINT to any descendant of a registered
  // top-level. Multiple passes handle grandchildren (e.g. combobox's inner
  // listbox is a grandchild of the test top-level).
  const topSet = new Set(Object.keys(r.windows).map(k => Number(k)));
  const painted = new Set(topSet);
  for (let pass = 0; pass < 4; pass++) {
    let progress = false;
    for (let s = 0; s < 256; s++) {
      const hw = e.wnd_slot_hwnd(s);
      if (!hw || painted.has(hw)) continue;
      const parent = e.wnd_get_parent ? e.wnd_get_parent(hw) : 0;
      if (!parent || !painted.has(parent)) continue;
      e.send_message(hw, 0x000F, 0, 0); // WM_PAINT
      painted.add(hw);
      progress = true;
    }
    if (!progress) break;
  }
}

// Convenience runner: each test exposes a (harness) => Promise<void> body
// and a name. We boot the harness, run the body, count colors, write the
// PNG, and exit non-zero on assertion failures.
async function runRenderTest(name, body, { minColors = 8 } = {}) {
  const checks = [];
  const check = (label, pass, info = '') => {
    checks.push({ label, pass });
    console.log((pass ? 'PASS  ' : 'FAIL  ') + label + (info ? '  (' + info + ')' : ''));
  };
  try {
    const harness = await bootRenderHarness();
    await body(harness, check);
    flushPendingPaints(harness);
    harness.renderer.repaint();
    const colors = countUniqueColors(harness.canvas);
    check(`canvas has ≥${minColors} distinct colors after repaint`,
      colors >= minColors, `${colors} colors`);
    const png = writePng(harness.canvas, `${name}.png`);
    console.log('wrote ' + png);
  } catch (err) {
    console.error(err);
    check('test body did not throw', false, err.message);
  }
  console.log('');
  const failed = checks.filter(c => !c.pass).length;
  console.log(`${checks.length - failed}/${checks.length} checks passed`);
  process.exit(failed > 0 ? 1 : 0);
}

// A caller may retain bootRenderHarness while this helper changes on disk.
// Evaluate its current bytes in a private Module, without evicting anyone's
// require cache or executing stale helper code under a new receipt.
function currentImplementation() {
  const source = fs.readFileSync(__filename);
  if (source.equals(evaluatedSource)) return null;
  if (!replacement || !replacement.source.equals(source)) {
    const fresh = new Module(__filename);
    fresh.filename = __filename;
    fresh.paths = module.paths;
    fresh.renderSource = source;
    fresh._compile(source.toString('utf8'), __filename);
    replacement = { source, exports: fresh.exports };
  }
  return replacement.exports;
}
module.exports = {};
for (const [name, fn] of Object.entries({ bootRenderHarness, mountBundledFonts, countUniqueColors,
  pixelMatches, writePng, runRenderTest })) {
  module.exports[name] = (...args) => {
    const current = currentImplementation();
    return current ? current[name](...args) : fn(...args);
  };
}
'use strict';

// Compile the FULL src tree for a test, through the canonical compiler.
//
// lib/compile-wat.js's compileWat was retired for full-tree builds (commit
// 24b79256): the src tree now spells region-symbolic operands — bare $REGION
// operands and `(data (region.addr ...))` segments — that the legacy compiler
// lowers to `unreachable` traps with only a warning instead of rejecting. A
// test that still went through it therefore compiled a module that traps at
// run time, or died outright on `unknown op: region.addr`.
//
// tools/watx-closure.js owns the source closure AND the option set, so a test
// that goes through here compiles exactly what tools/build.sh ships
// (tailCalls:true is the same artifact as build/wine-assembly.wasm). Do not
// inline the closure in a test — that is the drift the closure module exists
// to prevent.
//
// `transform(file, source) -> source` is the replacement for the old practice
// of passing compileWat a reader that patched one file on the way past (adding
// a test-only export to 13-exports.wat, say). It is called once per source
// file, with the bare basename ('13-exports.wat'). Note that watx-closure
// registers every file under THREE VFS keys — 'f', 'src/f' and './f' — because
// an (include ...) may spell any of them, so a patch must land on all three or
// the include that actually resolves silently gets the unpatched text; this
// helper does that for you.

const { watxSourceClosure, compileClosure } = require('../tools/watx-closure.js');

function compileSrcWasm(transform, { tailCalls = true } = {}) {
  const closure = watxSourceClosure();
  if (typeof transform === 'function') {
    const bases = [];
    for (const key of closure.vfs.keys()) {
      if (!key.includes('/')) bases.push(key);
    }
    for (const base of bases) {
      const out = transform(base, closure.vfs.get(base));
      if (out === undefined || out === closure.vfs.get(base)) continue;
      for (const key of [base, `src/${base}`, `./${base}`]) {
        if (closure.vfs.has(key)) closure.vfs.set(key, out);
      }
    }
  }
  const r = compileClosure(closure, { tailCalls });
  if (!r || !r.success || !r.wasmBinary) {
    const where = r && r.file ? ` at ${r.file}:${r.line || '?'}:${r.col || '?'}` : '';
    throw new Error(`compile-src: WATX compile failed${where}: ` +
      String((r && (r.error || r.message)) || 'compile() returned no binary'));
  }
  return Buffer.from(r.wasmBinary);
}

module.exports = { compileSrcWasm };
